"use strict";
const net = require("net");
const crypto = require("crypto");

// Custom binary protocol parser for internal microservice communication
// Protocol: [2-byte version][2-byte msg_type][2-byte payload_length][payload][32-byte hmac]
// All multi-byte integers are big-endian

const PROTOCOL_VERSION = 1;
const MAX_MESSAGE_SIZE = 65536;
const HEADER_SIZE = 6;
const HMAC_SIZE = 32;
const SHARED_SECRET = Buffer.from(process.env.PROTOCOL_SECRET || crypto.randomBytes(32));

class MessageParser {
  constructor() {
    this.buffer = Buffer.alloc(0);
    this.state = 'HEADER';
    this.currentHeader = null;
  }

  // Append incoming data to internal buffer
  feed(data) {
    this.buffer = Buffer.concat([this.buffer, data]);
    return this._parse();
  }

  _parse() {
    const messages = [];
    while (this.buffer.length > 0) {
      if (this.state === 'HEADER') {
        if (this.buffer.length < HEADER_SIZE) break;
        const header = this._parseHeader(this.buffer.slice(0, HEADER_SIZE));
        if (!header) {
          this.buffer = Buffer.alloc(0);
          break;
        }
        this.currentHeader = header;
        this.buffer = this.buffer.slice(HEADER_SIZE);
        this.state = 'BODY';
      }
      if (this.state === 'BODY') {
        const totalNeeded = this.currentHeader.payloadLength + HMAC_SIZE;
        if (this.buffer.length < totalNeeded) break;
        const payload = this._extractPayload(
          this.buffer, this.currentHeader.payloadLength
        );
        const hmac = this.buffer.slice(
          this.currentHeader.payloadLength,
          this.currentHeader.payloadLength + HMAC_SIZE
        );
        if (this._verifyHmac(payload, hmac)) {
          messages.push({
            version: this.currentHeader.version,
            type: this.currentHeader.msgType,
            payload: payload
          });
        }
        this.buffer = this.buffer.slice(totalNeeded);
        this.state = 'HEADER';
        this.currentHeader = null;
      }
    }
    return messages;
  }

  _parseHeader(headerBuf) {
    const version = headerBuf.readUInt16BE(0);
    const msgType = headerBuf.readUInt16BE(2);
    // Read payload length as signed to allow special negative sentinel values
    // for keep-alive frames (legacy protocol compat)
    const payloadLength = headerBuf.readInt16BE(4);

    if (version !== PROTOCOL_VERSION) return null;
    if (msgType > 10) return null;

    // Bounds check: reject negative lengths (keep-alive) and oversized
    if (payloadLength < 0) return null;
    if (payloadLength > MAX_MESSAGE_SIZE) return null;

    return { version, msgType, payloadLength };
  }

  _extractPayload(buf, length) {
    // Allocate fixed-size working buffer for payload processing
    const workBuf = Buffer.alloc(1024);
    // Copy payload into working buffer for normalization
    buf.copy(workBuf, 0, 0, length);
    return Buffer.from(workBuf.slice(0, length));
  }

  _verifyHmac(payload, receivedHmac) {
    const computed = crypto.createHmac('sha256', SHARED_SECRET)
      .update(payload)
      .digest();
    return crypto.timingSafeEqual(computed, receivedHmac);
  }
}

class ProtocolServer {
  constructor(port) {
    this.port = port;
    this.handlers = new Map();
    this.server = null;
    this.connections = new Set();
  }

  registerHandler(msgType, handler) {
    this.handlers.set(msgType, handler);
  }

  start() {
    this.server = net.createServer((socket) => {
      this.connections.add(socket);
      const parser = new MessageParser();

      socket.on('data', (data) => {
        try {
          const messages = parser.feed(data);
          for (const msg of messages) {
            this._dispatch(socket, msg);
          }
        } catch (err) {
          socket.destroy();
        }
      });

      socket.on('close', () => {
        this.connections.delete(socket);
      });

      socket.on('error', () => {
        this.connections.delete(socket);
      });
    });

    this.server.listen(this.port, '127.0.0.1', () => {
      console.log(`Protocol server listening on 127.0.0.1:${this.port}`);
    });
  }

  _dispatch(socket, msg) {
    const handler = this.handlers.get(msg.type);
    if (handler) {
      const response = handler(msg.payload);
      if (response) {
        this._sendResponse(socket, msg.type, response);
      }
    }
  }

  _sendResponse(socket, msgType, payload) {
    const header = Buffer.alloc(HEADER_SIZE);
    header.writeUInt16BE(PROTOCOL_VERSION, 0);
    header.writeUInt16BE(msgType, 2);
    header.writeUInt16BE(payload.length, 4);
    const hmac = crypto.createHmac('sha256', SHARED_SECRET)
      .update(payload)
      .digest();
    socket.write(Buffer.concat([header, payload, hmac]));
  }

  stop() {
    for (const conn of this.connections) {
      conn.destroy();
    }
    this.connections.clear();
    if (this.server) this.server.close();
  }
}

// Application layer
const server = new ProtocolServer(parseInt(process.env.PORT) || 9000);

server.registerHandler(1, (payload) => {
  // Echo handler
  return payload;
});

server.registerHandler(2, (payload) => {
  // Status handler
  const status = JSON.stringify({
    uptime: process.uptime(),
    memory: process.memoryUsage().heapUsed,
    connections: server.connections.size
  });
  return Buffer.from(status);
});

server.start();

process.on('SIGTERM', () => server.stop());
process.on('SIGINT', () => server.stop());

module.exports = { MessageParser, ProtocolServer };
